class Solution:
    def solve(self, spec_path: str = None) -> dict:
        code = r'''
import networkx as nx
from collections import defaultdict
import random
import math

class BroadCastTopology:
    def __init__(self, src: str, dsts: list, num_partitions: int):
        self.src = src
        self.dsts = dsts
        self.num_partitions = int(num_partitions)
        self.paths = {dst: {str(i): None for i in range(self.num_partitions)} for dst in dsts}

    def append_dst_partition_path(self, dst: str, partition: int, path: list):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

    def set_dst_partition_paths(self, dst: str, partition: int, paths: list):
        partition = str(partition)
        self.paths[dst][partition] = paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions


def search_algorithm(src, dsts, G, num_partitions):
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    num_vms = 2
    instance_rate = 0.54  # $/hour per instance

    # Provider-based bandwidth limits (Gbps per VM)
    ingress_limit_map = {"aws": 10, "gcp": 16, "azure": 16}
    egress_limit_map = {"aws": 5, "gcp": 7, "azure": 16}

    def get_provider(node):
        return node.split(":")[0] if ":" in node else "aws"

    def get_node_egress_gbps(node):
        provider = get_provider(node)
        return egress_limit_map.get(provider, 5) * num_vms

    def get_node_ingress_gbps(node):
        provider = get_provider(node)
        return ingress_limit_map.get(provider, 10) * num_vms

    # Try to determine data_vol from graph attributes
    data_vol_gb = 300.0  # default based on problem description
    if hasattr(G, 'graph'):
        if 'data_vol' in G.graph:
            data_vol_gb = float(G.graph['data_vol'])
        if 'num_vms' in G.graph:
            num_vms = int(G.graph['num_vms'])

    partition_size_gb = data_vol_gb / num_partitions

    def path_edges_list(path):
        edges = []
        for i in range(len(path) - 1):
            edges.append([path[i], path[i+1], dict(G[path[i]][path[i+1]])])
        return edges

    def path_cost_per_gb(path):
        total = 0.0
        for i in range(len(path) - 1):
            total += G[path[i]][path[i+1]].get("cost", 0.0)
        return total

    # Compute total cost matching the evaluator formula exactly:
    # C_egress = sum_e (|P_e| * s_partition * c_e)
    # t_transfer = max over all (dst, partition, edge in path) of (|P_e| * s_partition * 8 / f_e)
    # where f_e = min(edge_throughput, egress_limit/n_out_edges, ingress_limit/n_in_edges)
    # C_instance = |V| * n_vm * (r_instance / 3600) * t_transfer
    # Total = C_egress + C_instance

    def compute_cost_from_paths(dst_partition_paths):
        """
        dst_partition_paths: dict of {dst: {partition_id: [node_path]}}
        Returns total cost.
        """
        edge_partition_count = defaultdict(set)  # edge -> set of (dst, partition) pairs
        node_out_edges = defaultdict(set)  # node -> set of edges going out
        node_in_edges = defaultdict(set)   # node -> set of edges coming in
        nodes_used = set()

        for dst, partitions in dst_partition_paths.items():
            for p, node_path in partitions.items():
                if node_path is None:
                    continue
                for i in range(len(node_path) - 1):
                    u, v = node_path[i], node_path[i+1]
                    edge_partition_count[(u, v)].add((dst, p))
                    node_out_edges[u].add((u, v))
                    node_in_edges[v].add((u, v))
                    nodes_used.add(u)
                    nodes_used.add(v)

        if not edge_partition_count:
            return float('inf'), 0, 0, 0

        # Egress cost
        egress_cost = 0.0
        for (u, v), parts in edge_partition_count.items():
            cost_per_gb = G[u][v].get("cost", 0.0)
            egress_cost += len(parts) * partition_size_gb * cost_per_gb

        # Transfer time
        max_transfer_time = 0.0
        for (u, v), parts in edge_partition_count.items():
            edge_tp = G[u][v].get("throughput", 1.0)
            n_out = len(node_out_edges[u])
            eg_bw = get_node_egress_gbps(u) / max(n_out, 1)
            n_in = len(node_in_edges[v])
            ig_bw = get_node_ingress_gbps(v) / max(n_in, 1)
            actual_bw = min(edge_tp, eg_bw, ig_bw)
            if actual_bw <= 0:
                actual_bw = 0.001
            data_on_edge_gb = len(parts) * partition_size_gb
            tt = data_on_edge_gb * 8.0 / actual_bw
            max_transfer_time = max(max_transfer_time, tt)

        # Instance cost: |V| * n_vm * (r_instance / 3600) * t_transfer
        inst_cost = len(nodes_used) * num_vms * (instance_rate / 3600.0) * max_transfer_time

        total = egress_cost + inst_cost
        return total, egress_cost, inst_cost, max_transfer_time

    # Find K shortest paths for each destination
    K_PATHS = 30
    dst_candidate_paths = {}
    for dst in dsts:
        try:
            candidates = []
            gen = nx.shortest_simple_paths(G, src, dst, weight="cost")
            for i, path in enumerate(gen):
                if i >= K_PATHS:
                    break
                candidates.append(path)
            dst_candidate_paths[dst] = candidates
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            dst_candidate_paths[dst] = []

    # Also add shortest hop path and highest throughput path
    for dst in dsts:
        try:
            sp = nx.shortest_path(G, src, dst)
            if sp not in dst_candidate_paths[dst]:
                dst_candidate_paths[dst].append(sp)
        except:
            pass
        # Add path that maximizes minimum throughput
        try:
            # Weight by inverse throughput
            tp_weight = {}
            for u, v, d in G.edges(data=True):
                tp_weight[(u, v)] = 1.0 / max(d.get("throughput", 0.001), 0.001)
            G_tp = nx.DiGraph()
            for u, v, d in G.edges(data=True):
                G_tp.add_edge(u, v, weight=tp_weight[(u, v)])
            tp_path = nx.shortest_path(G_tp, src, dst, weight="weight")
            if tp_path not in dst_candidate_paths[dst]:
                dst_candidate_paths[dst].append(tp_path)
        except:
            pass

    # Strategy: Build assignment as {dst: {p: path_index}}
    # Convert to node paths for cost computation

    def assignment_to_paths(assignment):
        """Convert assignment dict {(dst,p): path_idx} to {dst: {p: node_path}}"""
        result = {}
        for dst in dsts:
            result[dst] = {}
            candidates = dst_candidate_paths.get(dst, [])
            for p in range(num_partitions):
                key = (dst, p)
                idx = assignment.get(key, 0)
                if candidates and idx < len(candidates):
                    result[dst][p] = candidates[idx]
                elif candidates:
                    result[dst][p] = candidates[0]
                else:
                    result[dst][p] = None
        return result

    def eval_assignment(assignment):
        paths = assignment_to_paths(assignment)
        total, _, _, _ = compute_cost_from_paths(paths)
        return total

    # ================================================================
    # Strategy 1: All partitions on cheapest path
    # ================================================================
    def strategy_cheapest():
        assignment = {}
        for dst in dsts:
            candidates = dst_candidate_paths[dst]
            if not candidates:
                continue
            for p in range(num_partitions):
                assignment[(dst, p)] = 0
        return assignment

    # ================================================================
    # Strategy 2: Spread partitions across paths (round-robin)
    # ================================================================
    def strategy_spread(n_paths=None):
        assignment = {}
        for dst in dsts:
            candidates = dst_candidate_paths[dst]
            if not candidates:
                continue
            n_use = min(len(candidates), n_paths or num_partitions)
            for p in range(num_partitions):
                assignment[(dst, p)] = p % n_use
        return assignment

    # ================================================================
    # Strategy 3: Greedy partition-by-partition assignment
    # ================================================================
    def strategy_greedy():
        assignment = {}

        # Process destinations sorted by number of candidates (most constrained first)
        dst_order = sorted(dsts, key=lambda d: len(dst_candidate_paths.get(d, [])))

        for dst in dst_order:
            candidates = dst_candidate_paths[dst]
            if not candidates:
                continue

            for p in range(num_partitions):
                best_idx = 0
                best_cost = float('inf')

                for idx in range(min(len(candidates), 15)):  # limit search
                    assignment[(dst, p)] = idx
                    cost = eval_assignment(assignment)
                    if cost < best_cost:
                        best_cost = cost
                        best_idx = idx

                assignment[(dst, p)] = best_idx

        return assignment

    # ================================================================
    # Strategy 4: Steiner tree - minimize nodes used
    # ================================================================
    def strategy_steiner():
        assignment = {}
        tree_nodes = {src}
        tree_edges = set()
        dst_paths = {}
        remaining = list(dsts)

        while remaining:
            best_dst = None
            best_path = None
            best_cost = float('inf')

            for dst in remaining:
                for tree_node in tree_nodes:
                    try:
                        path = nx.shortest_path(G, tree_node, dst, weight="cost")
                        cost = sum(G[path[i]][path[i+1]]["cost"] for i in range(len(path)-1))
                        # Bonus for reusing existing tree nodes
                        new_nodes = sum(1 for n in path if n not in tree_nodes)
                        adjusted_cost = cost + new_nodes * 0.01  # slight penalty for new nodes
                        if adjusted_cost < best_cost:
                            best_cost = adjusted_cost
                            best_path = path
                            best_dst = dst
                    except (nx.NetworkXNoPath, nx.NodeNotFound):
                        pass

            if best_dst is None:
                break

            remaining.remove(best_dst)
            for node in best_path:
                tree_nodes.add(node)
            for i in range(len(best_path)-1):
                tree_edges.add((best_path[i], best_path[i+1]))

            try:
                tree_graph = nx.DiGraph()
                for u, v in tree_edges:
                    tree_graph.add_edge(u, v, **G[u][v])
                full_path = nx.shortest_path(tree_graph, src, best_dst, weight="cost")
                dst_paths[best_dst] = full_path
            except:
                candidates = dst_candidate_paths.get(best_dst, [])
                if candidates:
                    dst_paths[best_dst] = candidates[0]

        for dst in dsts:
            if dst in dst_paths:
                path = dst_paths[dst]
                candidates = dst_candidate_paths[dst]
                path_idx = None
                for idx, cp in enumerate(candidates):
                    if cp == path:
                        path_idx = idx
                        break
                if path_idx is None:
                    candidates.append(path)
                    path_idx = len(candidates) - 1
                for p in range(num_partitions):
                    assignment[(dst, p)] = path_idx
            else:
                for p in range(num_partitions):
                    assignment[(dst, p)] = 0

        return assignment

    # ================================================================
    # Strategy 5: Balance egress cost vs congestion
    # Weight = cost + lambda * (congestion penalty)
    # ================================================================
    def strategy_weighted(lam=0.1):
        """Use weighted shortest paths where weight = cost + lam * 1/throughput"""
        assignment = {}
        for dst in dsts:
            # Find path with combined weight
            try:
                def weight_fn(u, v, d):
                    return d.get("cost", 0) + lam / max(d.get("throughput", 0.001), 0.001)
                path = nx.dijkstra_path(G, src, dst, weight=weight_fn)
                candidates = dst_candidate_paths[dst]
                path_idx = None
                for idx, cp in enumerate(candidates):
                    if cp == path:
                        path_idx = idx
                        break
                if path_idx is None:
                    candidates.append(path)
                    path_idx = len(candidates) - 1
                for p in range(num_partitions):
                    assignment[(dst, p)] = path_idx
            except:
                for p in range(num_partitions):
                    assignment[(dst, p)] = 0
        return assignment

    # ================================================================
    # Strategy 6: Minimize nodes - use shortest hop paths only
    # ================================================================
    def strategy_min_nodes():
        assignment = {}
        for dst in dsts:
            try:
                path = nx.shortest_path(G, src, dst)  # fewest hops
                candidates = dst_candidate_paths[dst]
                path_idx = None
                for idx, cp in enumerate(candidates):
                    if cp == path:
                        path_idx = idx
                        break
                if path_idx is None:
                    candidates.append(path)
                    path_idx = len(candidates) - 1
                for p in range(num_partitions):
                    assignment[(dst, p)] = path_idx
            except:
                for p in range(num_partitions):
                    assignment[(dst, p)] = 0
        return assignment

    # ================================================================
    # Evaluate all strategies
    # ================================================================
    strategies = [
        ("cheapest", lambda: strategy_cheapest()),
        ("spread2", lambda: strategy_spread(2)),
        ("spread3", lambda: strategy_spread(3)),
        ("spread4", lambda: strategy_spread(4)),
        ("spread5", lambda: strategy_spread(5)),
        ("steiner", lambda: strategy_steiner()),
        ("weighted_0.01", lambda: strategy_weighted(0.01)),
        ("weighted_0.1", lambda: strategy_weighted(0.1)),
        ("weighted_1.0", lambda: strategy_weighted(1.0)),
        ("min_nodes", lambda: strategy_min_nodes()),
    ]

    best_assignment = None
    best_total_cost = float('inf')
    best_name = ""

    for name, strat_fn in strategies:
        try:
            assignment = strat_fn()
            cost = eval_assignment(assignment)
            if cost < best_total_cost:
                best_total_cost = cost
                best_assignment = assignment
                best_name = name
        except Exception as e:
            pass

    # Try greedy (slower) only if we have time
    n_items = num_partitions * len(dsts)
    if n_items <= 100:  # only for smaller instances
        try:
            assignment = strategy_greedy()
            cost = eval_assignment(assignment)
            if cost < best_total_cost:
                best_total_cost = cost
                best_assignment = assignment
                best_name = "greedy"
        except:
            pass

    if best_assignment is None:
        best_assignment = strategy_cheapest()
        best_total_cost = eval_assignment(best_assignment)

    # ================================================================
    # Simulated annealing improvement
    # ================================================================
    current_assignment = dict(best_assignment)
    current_cost = best_total_cost
    sa_best_assignment = dict(best_assignment)
    sa_best_cost = best_total_cost

    random.seed(42)

    temperature = max(current_cost * 0.05, 1.0)
    cooling_rate = 0.997

    max_iters = min(5000, n_items * 20)

    all_keys = [(dst, p) for dst in dsts for p in range(num_partitions)]

    for iteration in range(max_iters):
        if not all_keys:
            break

        key = random.choice(all_keys)
        dst, p = key

        candidates = dst_candidate_paths.get(dst, [])
        if not candidates or len(candidates) <= 1:
            continue

        current_idx = current_assignment.get(key, 0)
        new_idx = random.randint(0, len(candidates) - 1)
        if new_idx == current_idx:
            continue

        old_assignment = dict(current_assignment)
        current_assignment[key] = new_idx
        new_cost = eval_assignment(current_assignment)

        delta = new_cost - current_cost

        if delta < 0 or (temperature > 0 and random.random() < math.exp(-delta / max(temperature, 1e-10))):
            current_cost = new_cost
            if current_cost < sa_best_cost:
                sa_best_cost = current_cost
                sa_best_assignment = dict(current_assignment)
        else:
            current_assignment = old_assignment

        temperature *= cooling_rate

    if sa_best_cost < best_total_cost:
        best_assignment = sa_best_assignment
        best_total_cost = sa_best_cost

    # ================================================================
    # Hill climbing refinement
    # ================================================================
    improved = True
    hc_rounds = 0
    while improved and hc_rounds < 3:
        improved = False
        hc_rounds += 1
        for key in all_keys:
            dst, p = key
            candidates = dst_candidate_paths.get(dst, [])
            if not candidates or len(candidates) <= 1:
                continue

            current_idx = best_assignment.get(key, 0)
            best_local_cost = best_total_cost
            best_local_idx = current_idx

            for idx in range(len(candidates)):
                if idx == current_idx:
                    continue
                best_assignment[key] = idx
                cost = eval_assignment(best_assignment)
                if cost < best_local_cost:
                    best_local_cost = cost
                    best_local_idx = idx

            if best_local_idx != current_idx:
                best_assignment[key] = best_local_idx
                best_total_cost = best_local_cost
                improved = True
            else:
                best_assignment[key] = current_idx

    # ================================================================
    # Build final topology
    # ================================================================
    for dst in dsts:
        candidates = dst_candidate_paths.get(dst, [])
        if not candidates:
            continue
        for p in range(num_partitions):
            key = (dst, p)
            path_idx = best_assignment.get(key, 0)
            if path_idx >= len(candidates):
                path_idx = 0
            path = candidates[path_idx]
            edges = path_edges_list(path)
            bc_topology.set_dst_partition_paths(dst, p, edges)

    return bc_topology
